'use strict';
let works=[],selected='',activeZone=-1;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function filtered(){const q=$('#search').value.toLowerCase(),scope=$('#scope').value;return works.filter(w=>(scope==='all'||w.scope===scope)&&[w.title,w.zh,w.year,w.cr,w.collection].join(' ').toLowerCase().includes(q));}
function list(){const rows=filtered();$('#count').textContent=`${rows.length} 件`;let decade='';$('#list').innerHTML=rows.length?rows.map(w=>{const dec=Math.floor(w.sortYear/10)*10;let h='';if(dec!==decade){decade=dec;h=`<p class="year-head">${dec}年代</p>`;}return h+`<button class="work-item" data-id="${esc(w.cr)}" aria-current="${w.cr===selected}"><img loading="lazy" src="${esc(w.localImage)}" alt=""><span><strong>${esc(w.zh)}</strong><small>${esc(w.year)} · ${esc(w.cr)}</small></span></button>`;}).join(''):'<p class="empty">没有匹配作品。试试英文名称或年份。</p>';$('#list').querySelectorAll('button').forEach(b=>b.onclick=()=>select(b.dataset.id));}
function select(id){const w=works.find(x=>x.cr===id);if(!w)return;selected=id;activeZone=-1;history.replaceState(null,'','#work-'+encodeURIComponent(id));list();$('#detail').innerHTML=`<div class="work-title"><div><div class="indexno">${esc(w.year)} / CR ${esc(w.cr)} · ${w.scope==='core'?'教皇主题':'边界与关联'}</div><h2>${esc(w.zh)}</h2><p class="original-title">${esc(w.title)}</p></div></div><div class="view-layout"><div><div class="image-well"><div class="image-plane"><img class="painting" src="${esc(w.localImage)}" alt="${esc(w.zh)}，${esc(w.year)}"><div class="grid-overlay"></div><div class="hotspot"></div></div></div><div class="image-tools"><button id="grid" aria-pressed="false">显示定位网格</button><a href="${esc(w.localImage)}" target="_blank">打开大图 ↗</a></div><p class="credit">参考图像：培根遗产管理机构。© The Estate of Francis Bacon / DACS。${w.recordOnly?'本条为历史记录，参考图不代表作品现仍存在。':''}</p>${w.zones?.length?`<div class="observations">${w.zones.map((z,i)=>`<button class="detail-button" data-zone="${i}" aria-pressed="false">${i+1} · ${esc(z.label)}</button>`).join('')}</div><p class="note" id="zone-note">点选细节，在画面中定位。</p>`:''}</div><div><dl><div><dt>材料 / 尺寸（高 × 宽）</dt><dd>${esc(w.medium)}<br>${esc(w.dimensions)}</dd></div><div><dt>公开记录中的收藏地</dt><dd>${esc(w.collection)}</dd></div><div><dt>所在地说明</dt><dd>${esc(w.locationNote)}</dd></div></dl><div class="reading"><h3>创作与系列位置</h3><p>${esc(w.context)}</p><h3>图像观察 / 本页解读</h3><p>${esc(w.reading)}</p><h3>联系着看</h3><p>${esc(w.connection)}</p></div><div class="source-links"><a href="${esc(w.source)}" target="_blank" rel="noreferrer">作品目录原条目 ↗</a>${(w.sources||[]).map(s=>`<br><a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.label)} ↗</a>`).join('')}</div></div></div>`;
 const im=$('.painting');im.onload=()=>{const plane=$('.image-plane');if(!plane)return;const h=Math.min(im.naturalHeight,630),ratio=im.naturalWidth/im.naturalHeight;plane.style.maxWidth=`${h*ratio}px`;};
 $('#grid').onclick=()=>{const on=$('.image-plane').classList.toggle('has-grid');$('#grid').setAttribute('aria-pressed',on);$('#grid').textContent=on?'隐藏定位网格':'显示定位网格';};
 document.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>{let i=+b.dataset.zone;activeZone=activeZone===i?-1:i;const z=w.zones[i],box=$('.hotspot');box.classList.toggle('on',activeZone>=0);if(activeZone>=0){box.style.left=z.box[0]*100+'%';box.style.top=z.box[1]*100+'%';box.style.width=z.box[2]*100+'%';box.style.height=z.box[3]*100+'%';}$('#zone-note').textContent=activeZone<0?'点选细节，在画面中定位。':z.text;document.querySelectorAll('[data-zone]').forEach(x=>x.setAttribute('aria-pressed',+x.dataset.zone===activeZone));});
}
fetch('data.json').then(r=>{if(!r.ok)throw Error('载入失败');return r.json();}).then(d=>{works=d.works;$('#coverage').textContent=d.coverage;$('#scope-note').textContent=d.scopeNote;const id=decodeURIComponent(location.hash.replace('#work-',''));select(works.some(w=>w.cr===id)?id:'53-02');$('#search').oninput=list;$('#scope').onchange=list;}).catch(()=>{$('#coverage').textContent='目录暂时无法载入，请刷新页面。';$('#detail').textContent='作品资料加载失败。';});
